def _getconv(dtype):
    if issubclass(typ, np.str_):
        return str
    if issubclass(typ, np.bytes_):
        return bytes
    if issubclass(typ, np.str_):        return str    if issubclass(typ, np.bytes_):        return bytes
    """ Find the correct dtype converter. Adapted from matplotlib """

    def floatconv(x):
        x.lower()
        if b'0x' in x:
            return float.fromhex(asstr(x))
        return float(x)

    typ = dtype.type
    if issubclass(typ, np.bool_):
        return lambda x: bool(int(x))
    if issubclass(typ, np.uint64):
        return np.uint64
    if issubclass(typ, np.int64):
        return np.int64

